import UIKit

protocol SessionValueManagerProtocol {
    var sessionValue: UInt64 { get }

    /// - Parameter value: The session value, or `nil` to generate a new one.
    /// The value is sent in the event as a number and parsed by the receiving side as `Int64`,
    /// so it must fit into `Int64.max` — values generated by the SDK always fit
    func setSessionValue(_ value: UInt64?)
    /// - Parameters:
    ///   - handler: Handler for session value updates
    ///   - owner: The SDK instance setting the handler. One owner — one handler:
    ///   setting it again replaces the previous one instead of adding another
    func setOnSessionValueUpdated(_ handler: @escaping (UInt64?) -> Void, for owner: AnyObject)
}

/// Stores the client session identifier shared by all SDK instances in the app.
///
/// The shared value is maintained on two levels:
/// 1. `shared` — a single manager for all `WBAnalytics`/receivers within one loaded copy of the framework;
/// 2. exchange via `NotificationCenter.default` — if the SDK is linked into several app modules,
///    the process hosts several copies of `SessionValueManager.shared`, each with its own state.
///    `NotificationCenter` is provided by Foundation and is unique in the process, so the copies coordinate
///    through it: a new copy asks the existing ones for the current value when it is created,
///    and any value change is broadcast to the others.
///
/// Only Foundation types (`NSNumber`, `NSString`, `NSMutableDictionary`) cross the boundary between copies:
/// each copy has its own Swift type metadata, so the SDK's own types would not survive a cast through `userInfo`.
final class SessionValueManager {
    static let shared = SessionValueManager()

    // MARK: - Properties

    private let notificationCenter: NotificationCenter
    private let lock = NSLock()

    private var currentSessionValue: UInt64 = 0
    /// Sequence number of the latest value change. Handlers are notified outside the lock, so while that
    /// is being prepared another thread may have changed the value — a stale notification is dropped by its number.
    private var sessionValueGeneration: UInt64 = 0
    private var handlerEntries = [ObjectIdentifier: HandlerEntry]()
    /// Indicates that another SDK copy has already generated the value for the current foreground transition.
    /// Set by a broadcast, cleared by this copy's own `willEnterForeground` handler.
    private var isForegroundValueAdopted = false

    // MARK: - Init

    init(notificationCenter: NotificationCenter = .default) {
        self.notificationCenter = notificationCenter

        // The value is taken from already running SDK copies, and only if there are none is a new one generated.
        // It is generated here rather than on didFinishLaunchingNotification: that notification
        // fires after the first_open event is sent, and that event already needs the value.
        currentSessionValue = requestedSessionValueFromOtherInstances() ?? Self.makeSessionValue()

        // Subscribe last: before this line the value is not ready yet, and a request from another copy
        // would have to be answered with zero, which it would take for a valid shared identifier
        subscribeForNotifications()
    }

    // MARK: - Deinit

    deinit {
        notificationCenter.removeObserver(self)
    }
}

// MARK: - SessionValueManagerProtocol

extension SessionValueManager: SessionValueManagerProtocol {
    var sessionValue: UInt64 {
        lock.lock()
        defer { lock.unlock() }
        return currentSessionValue
    }

    func setSessionValue(_ value: UInt64?) {
        guard let value else {
            updateSessionValue(Self.makeSessionValue(), reason: .explicit)
            return
        }
        updateSessionValue(value, reason: .explicit)
    }

    /// Handlers are stored per owner: there may be several SDK instances in the app,
    /// and each subscribes to updates of the shared value independently of the others.
    /// Setting a handler again from the same owner replaces it — otherwise closures
    /// would accumulate, retaining the objects they capture.
    func setOnSessionValueUpdated(_ handler: @escaping (UInt64?) -> Void, for owner: AnyObject) {
        lock.lock()
        handlerEntries[ObjectIdentifier(owner)] = HandlerEntry(owner: owner, handler: handler)
        let value = currentSessionValue
        lock.unlock()

        handler(value)
    }
}

// MARK: - Notifications

private extension SessionValueManager {
    func subscribeForNotifications() {
        notificationCenter.addObserver(
            self,
            selector: #selector(didFinishLaunching),
            name: UIApplication.didFinishLaunchingNotification,
            object: nil
        )

        notificationCenter.addObserver(
            self,
            selector: #selector(willEnterForeground),
            name: UIApplication.willEnterForegroundNotification,
            object: nil
        )

        notificationCenter.addObserver(
            self,
            selector: #selector(didCloseApp),
            name: UIApplication.didEnterBackgroundNotification,
            object: nil
        )

        notificationCenter.addObserver(
            self,
            selector: #selector(didCloseApp),
            name: UIApplication.willTerminateNotification,
            object: nil
        )

        notificationCenter.addObserver(
            self,
            selector: #selector(sessionValueRequested(_:)),
            name: Notification.Name(Constants.sessionValueRequestedName),
            object: nil
        )

        notificationCenter.addObserver(
            self,
            selector: #selector(sessionValueChangedByOtherInstance(_:)),
            name: Notification.Name(Constants.sessionValueChangedName),
            object: nil
        )
    }

    @objc func didFinishLaunching() {
        // The value is already available at this point: it is resolved by the initializer, because
        // didFinishLaunchingNotification arrives after the first_open event has been sent
        notifyHandlers(with: sessionValue)
    }

    @objc func willEnterForeground() {
        lock.lock()
        // Another SDK copy has already generated the value for this transition and broadcast it:
        // the system notification reaches all copies on the main thread one after another, so
        // only the copy whose handler runs first generates it, and the rest pick up its value.
        let isAdopted = isForegroundValueAdopted
        isForegroundValueAdopted = false
        lock.unlock()

        // The value has already been picked up from the broadcast and handlers were notified at that moment,
        // so notifying again here would only duplicate the call
        guard !isAdopted else { return }

        updateSessionValue(Self.makeSessionValue(), reason: .foreground)
    }

    @objc func didCloseApp() {
        lock.lock()
        isForegroundValueAdopted = false
        lock.unlock()

        notifyHandlers(with: nil)
    }

    /// Reply to a request from a newly created SDK copy: hand it the current value
    /// so that it does not generate its own. Filled synchronously, inside `post`.
    @objc func sessionValueRequested(_ notification: Notification) {
        guard !isOwn(notification),
              let box = notification.userInfo?[Constants.sessionValueBoxKey] as? NSMutableDictionary
        else { return }

        box[Constants.sessionValueKey] = NSNumber(value: sessionValue)
    }

    @objc func sessionValueChangedByOtherInstance(_ notification: Notification) {
        guard !isOwn(notification),
              let value = (notification.userInfo?[Constants.sessionValueKey] as? NSNumber)?.uint64Value
        else { return }

        let isForegroundReason = notification.userInfo?[Constants.reasonKey] as? String == Reason.foreground.rawValue

        lock.lock()
        currentSessionValue = value
        sessionValueGeneration &+= 1
        let generation = sessionValueGeneration
        if isForegroundReason {
            isForegroundValueAdopted = true
        }
        lock.unlock()

        notifyHandlers(with: value, generation: generation)
    }

    /// The subscription uses `object: nil`, so a copy also receives its own broadcasts — those are skipped.
    func isOwn(_ notification: Notification) -> Bool {
        (notification.object as AnyObject?) === self
    }
}

// MARK: - Private methods

private extension SessionValueManager {
    struct HandlerEntry {
        weak var owner: AnyObject?
        let handler: (UInt64?) -> Void
    }

    enum Reason: String {
        /// The value changed because the app entered the foreground
        case foreground
        /// The value was set by the SDK client or generated outside the foreground lifecycle
        case explicit
    }

    func updateSessionValue(_ value: UInt64, reason: Reason) {
        let generation = storeSessionValue(value)

        // Broadcasting and calling handlers happen outside the lock: a client handler may call back into the SDK,
        // and `post` synchronously runs the handlers of other SDK copies.
        notificationCenter.post(
            name: Notification.Name(Constants.sessionValueChangedName),
            object: self,
            userInfo: [
                Constants.sessionValueKey: NSNumber(value: value),
                Constants.reasonKey: reason.rawValue
            ]
        )

        notifyHandlers(with: value, generation: generation)
    }

    /// - Returns: The sequence number of this value change
    func storeSessionValue(_ value: UInt64) -> UInt64 {
        lock.lock()
        defer { lock.unlock() }

        currentSessionValue = value
        sessionValueGeneration &+= 1

        return sessionValueGeneration
    }

    /// Asks other SDK copies in the process for the value. `post` is synchronous, so by the time
    /// it returns the box is already filled if at least one copy replied.
    func requestedSessionValueFromOtherInstances() -> UInt64? {
        let box = NSMutableDictionary()

        notificationCenter.post(
            name: Notification.Name(Constants.sessionValueRequestedName),
            object: self,
            userInfo: [Constants.sessionValueBoxKey: box]
        )

        return (box[Constants.sessionValueKey] as? NSNumber)?.uint64Value
    }

    /// - Parameter generation: Sequence number of the value change being notified about. If by this time
    /// another thread has changed the value, the notification is dropped: handlers have already received
    /// a newer value, and the old one would only confuse them
    func notifyHandlers(with value: UInt64?, generation: UInt64? = nil) {
        lock.lock()
        guard generation == nil || generation == sessionValueGeneration else {
            lock.unlock()
            return
        }
        // Owners are held weakly, so an SDK instance's handler goes away together with the instance
        handlerEntries = handlerEntries.filter { $0.value.owner != nil }
        let handlers = handlerEntries.values.map(\.handler)
        lock.unlock()

        handlers.forEach { $0(value) }
    }

    static func makeSessionValue() -> UInt64 {
        let timestamp = UInt64(Date().timeIntervalSince1970 * 1000)
        let randomValue = UInt64.random(in: 0...999_999)
        let shiftedTimestamp = timestamp << Constants.timestampShift

        return shiftedTimestamp | randomValue
    }
}

// MARK: - Constants

private extension SessionValueManager {
    enum Constants {
        static let timestampShift: UInt64 = 20
        static let sessionValueRequestedName = "ru.wildanalytics.analytics.sessionValue.requested"
        static let sessionValueChangedName = "ru.wildanalytics.analytics.sessionValue.changed"
        static let sessionValueKey = "session_value"
        static let sessionValueBoxKey = "session_value_box"
        static let reasonKey = "reason"
    }
}
